using System.Text.Json;
using Dapper;
using Monergy.Contracts;
using Monergy.Platform;
using Monergy.Services.FinancialRules.Application;
using Npgsql;
namespace Monergy.Services.FinancialRules.Infrastructure;
public sealed class PostgresDebtToIncomeCalculations:IDebtToIncomeCalculationRepository,IAsyncDisposable
{
    private readonly NpgsqlDataSource source;
    public PostgresDebtToIncomeCalculations(IConfiguration config){PhysicalPersistenceGuard.EnsureAllowed(config);source=NpgsqlDataSource.Create(PhysicalPersistenceGuard.Require(config,"Monergy:Persistence:FinancialRules:RuntimeConnection"));}
    public async Task<DebtToIncomeCalculation> CreateAsync(string tenant,string customer,string actor,string fingerprint,DebtToIncomeCalculation value,CancellationToken ct)
    {await using var db=await source.OpenConnectionAsync(ct).ConfigureAwait(false);await using var tx=await db.BeginTransactionAsync(ct).ConfigureAwait(false);var args=new{Tenant=tenant,Customer=customer,Id=value.CalculationId,Actor=actor,value.OperationId,Fingerprint=fingerprint,Payload=JsonSerializer.Serialize(value,ContractJson.Options),value.RecordedAt};await db.ExecuteAsync(new CommandDefinition("SELECT pg_advisory_xact_lock(hashtextextended(@Id,0));",new{Id=JsonSerializer.Serialize(new[]{tenant,customer,actor,value.OperationId})},tx,cancellationToken:ct)).ConfigureAwait(false);var prior=await db.QuerySingleOrDefaultAsync<Stored>(new CommandDefinition("SELECT fingerprint AS Fingerprint,payload::text AS Payload FROM financial_rules.debt_to_income_results WHERE tenant_id=@Tenant AND customer_id=@Customer AND calculation_id=@Id;",args,tx,cancellationToken:ct)).ConfigureAwait(false);if(prior is not null){if(prior.Fingerprint!=fingerprint||Decode(prior.Payload).RecordedBy!=actor)throw new TenantBoundaryException("DEBT_TO_INCOME_OPERATION_CONFLICT",409);await tx.CommitAsync(ct).ConfigureAwait(false);return Decode(prior.Payload);}await db.ExecuteAsync(new CommandDefinition("INSERT INTO financial_rules.debt_to_income_results(tenant_id,customer_id,calculation_id,actor_id,operation_id,fingerprint,payload,recorded_at) VALUES(@Tenant,@Customer,@Id,@Actor,@OperationId,@Fingerprint,CAST(@Payload AS jsonb),@RecordedAt);",args,tx,cancellationToken:ct)).ConfigureAwait(false);await tx.CommitAsync(ct).ConfigureAwait(false);return value;}
    public async Task<DebtToIncomeCalculation?> ReadAsync(string tenant,string customer,string id,CancellationToken ct){await using var db=await source.OpenConnectionAsync(ct).ConfigureAwait(false);var payload=await db.QuerySingleOrDefaultAsync<string>(new CommandDefinition("SELECT payload::text FROM financial_rules.debt_to_income_results WHERE tenant_id=@Tenant AND customer_id=@Customer AND calculation_id=@Id;",new{Tenant=tenant,Customer=customer,Id=id},cancellationToken:ct)).ConfigureAwait(false);return payload is null?null:Decode(payload);}
    public async Task<DebtToIncomeCalculationPage> ListAsync(string tenant,string customer,string? beforeId,CancellationToken ct){var before=beforeId is null?null:await ReadAsync(tenant,customer,beforeId,ct).ConfigureAwait(false)??throw new TenantBoundaryException("DEBT_TO_INCOME_NOT_FOUND",404);await using var db=await source.OpenConnectionAsync(ct).ConfigureAwait(false);var rows=(await db.QueryAsync<string>(new CommandDefinition("SELECT payload::text FROM financial_rules.debt_to_income_results WHERE tenant_id=@Tenant AND customer_id=@Customer AND (@BeforeAt IS NULL OR (recorded_at,calculation_id)<(@BeforeAt,@BeforeId)) ORDER BY recorded_at DESC,calculation_id DESC LIMIT 51;",new{Tenant=tenant,Customer=customer,BeforeAt=(DateTimeOffset?)before?.RecordedAt,BeforeId=beforeId},cancellationToken:ct)).ConfigureAwait(false)).Select(Decode).ToArray();return new(rows.Take(50).ToArray(),rows.Length>50,rows.Length>50?rows[49].CalculationId:null);}
    private static DebtToIncomeCalculation Decode(string payload)=>JsonSerializer.Deserialize<DebtToIncomeCalculation>(payload,ContractJson.Options)??throw new TenantBoundaryException("DEBT_TO_INCOME_UNAVAILABLE",503);private sealed record Stored(string Fingerprint,string Payload);public ValueTask DisposeAsync()=>source.DisposeAsync();
}
